\label{t:de Rham}
Let ${\cal F}$ be a Riemannian foliation on a
closed manifold $M$ with a bundle-like metric. Then
$\Pi$ defines a continuous operator on $\Omega$, we
have the leafwise Hodge decomposition
\begin{equation}\label{e:leafwise Hodge}
\Omega=\ker{\Delta}_0\oplus\overline{\mbox{\rm im}\;{\Delta}_0}
=(\ker d_{0,1}\cap\ker\delta_{0,-1})\oplus\overline{\mbox{\rm im}\; d_{0,1}}
\oplus\overline{\mbox{\rm im}\;\delta_{0,-1}}\;,
\end{equation}
and $(t,\alpha)\mapsto e^{-t{\Delta}_0}\alpha$ defines a continuous map
$[0,\infty]\times\Omega\rightarrow\Omega$.

\label{l:key'}
There are bounded operators $B_1,\ldots,B_5$ on $W^l(E)$ such that
\begin{eqnarray*}
Ad\pm dA&=&B_1d+dB_2\;,\\
A\delta\pm\delta A&=&B_1\delta+\delta B_2\;,\\
{[A,{\Delta}]}&=&B_3{\Delta} + {\Delta} B_4 + D B_5 D\;.
\end{eqnarray*}

Consider the following bounded compositions:
\begin{equation}\label{e:composition1}
\mbox{\begin{picture}(166,22)
\put(0,0){$W^{l+1}(E)$}
\put(43,3){\vector(1,0){30}}
\put(46,6){$e^{-t{\Delta}}$}
\put(77,0){$W^{l+1}(E)\hookrightarrow W^l(E)\;,$}
\end{picture}}
\end{equation}
\begin{equation}\label{e:composition2}
\mbox{\begin{picture}(176,17)
\put(0,0){$W^{l+1}(E)$}
\put(43,3){\vector(1,0){30}}
\put(46,6){$e^{-t{\Delta}}$}
\put(77,0){$W^{l+1}(E)$}
\put(120,3){\vector(1,0){20}}
\put(125,6){$D$}
\put(144,0){$W^l(E)\;,$}
\end{picture}}
\end{equation}
\begin{equation}\label{e:composition3}
\mbox{\begin{picture}(192,17)
\put(0,0){$W^{l+1}(E)$}
\put(43,3){\vector(1,0){30}}
\put(46,6){$e^{-t{\Delta}}$}
\put(77,0){$W^{l+1}(E)$}
\put(120,3){\vector(1,0){36}}
\put(123,6){$A+B$}
\put(160,0){$W^l(E)\;.$}
\end{picture}}
\end{equation}
By~(\ref{e:norm'}), it is enough to prove
that the compositions~(\ref{e:composition1}),~(\ref{e:composition2})
and~(\ref{e:composition3}) are strongly convergent as $t\rightarrow\infty$, and to
prove the continuous extension to $[0,\infty]\times  W^{l+1}(E)$ of the maps
$[0,\infty)\times W^{l+1}(E)\rightarrow W^l(E)$ defined by these time dependent
operators. This holds for~(\ref{e:composition1}) and~(\ref{e:composition2})
by property~(iv) for $k=l$ since these operators are respectively equal to
the compositions
\begin{center}
\begin{picture}(166,43)
\put(5,26){$W^{l+1}(E)\hookrightarrow W^l(E)$}
\put(95,29){\vector(1,0){30}}
\put(98,32){$e^{-t{\Delta}}$}
\put(129,26){$W^l(E)\;,$}
\put(0,0){$W^{l+1}(E)$}
\put(43,3){\vector(1,0){20}}
\put(48,6){$D$}
\put(67,0){$W^l(E)$}
\put(100,3){\vector(1,0){30}}
\put(103,6){$e^{-t{\Delta}}$}
\put(134,0){$W^l(E)\;.$}
\end{picture}
\end{center}

On the other hand,~(\ref{e:composition3}) is the sum
of the bounded compositions 
\begin{equation}\label{e:composition4}
\mbox{\begin{picture}(196,17)
\put(0,0){$W^{l+1}(E)\hookrightarrow W^l(E)$}
\put(90,3){\vector(1,0){70}}
\put(93,9){$\left[A+B,e^{-t{\Delta}}\right]$}
\put(164,0){$W^l(E)\;,$}
\end{picture}}
\end{equation}
\begin{equation}\label{e:composition5}
\mbox{\begin{picture}(182,17)
\put(0,0){$W^{l+1}(E)$}
\put(43,3){\vector(1,0){36}}
\put(46,6){$A+B$}
\put(83,0){$W^l(E)$}
\put(116,3){\vector(1,0){30}}
\put(119,6){$e^{-t{\Delta}}$}
\put(150,0){$W^l(E)\;.$}
\end{picture}}
\end{equation}
Now Lemma~\ref{l:[A+B,e]} and property~(iv) for $k=l$ respectively
imply the strong convergence of (\ref{e:composition4}) and
(\ref{e:composition5}) as $t\rightarrow\infty$, as well as the continuous extension to 
$[0,\infty]\times W^{l+1}(E)$ of the maps
$[0,\infty)\times W^{l+1}(E)\rightarrow W^l(E)$ defined by both of these
time dependent operators.~$\Box$

\label{l:self-adjoint}
$D_1$ and $\widetilde D_1$ are essentially self-adjoint in $L^2{\cal
H}_1$ and $L^2\widetilde{\cal H}_1$, respectively.

\label{l:Sobolev}
We have the following properties:
\begin{itemize}

\item[$($i$)$] $D\Pi-\Pi D_\perp\Pi$ defines a bounded operator on $L^2\Omega$.

\item[$($ii$)$] For each $v\in{\bf Z}$, 
$D\widetilde\Pi_{\cdot,v}
-\widetilde\Pi_{\cdot,v}D\widetilde\Pi_{\cdot,v}$ defines a
bounded operator on $L^2\Omega$.

\end{itemize}
